args.command:
cd /tmp/eval-work-gbSXME && cat > compare.mjs <<'EOF'
import { processBatch, classifySignal } from './out_new/new.js';

// Reference implementations of the ORIGINAL logic (from the pre-edit file).
const MAX_READINGS = 500;
const UNITS = ["uV","mV","V"];
function origClassify(mv){
  if(mv>=0&&mv<50)return"standby";
  if(mv>=50&&mv<200)return"idle";
  if(mv>=200&&mv<600)return"active";
  if(mv>=600&&mv<900)return"loaded";
  if(mv>=900)return"critical";
  return"negative";
}
function origSeverity(label){
  if(label==="negative")return 5;
  if(label==="critical")return 4;
  if(label==="loaded")return 3;
  if(label==="active")return 2;
  if(label==="idle")return 1;
  return 0;
}
function origProcess(raw){
  const be=origValidate(raw);
  if(be!==null)return{ok:false,error:be};
  const entries=raw.readings;
  const parsed=[];
  for(let i=0;i<entries.length;i++){
    const o=origParse(entries[i],i);
    if(typeof o==="string")return{ok:false,error:o};
    parsed.push({channel:o.channel,millivolts:origNorm(o.unit,o.value),at:o.at});
  }
  const labels=parsed.map(r=>origClassify(r.millivolts));
  const alerts=origAlerts(parsed);
  const channels=origSummaries(parsed,labels);
  const report=origReport(parsed.length,Object.keys(channels).length,alerts.length,labels);
  return{ok:true,readings:parsed.length,labels,channels,alerts,report};
}
function origValidate(raw){
  if(typeof raw!=="object"||raw===null)return"malformed batch";
  if(!Array.isArray(raw.readings))return"missing readings";
  if(raw.readings.length===0)return"empty batch";
  if(raw.readings.length>MAX_READINGS)return"batch too large";
  return null;
}
function origParse(entry,index){
  if(typeof entry!=="object"||entry===null)return"reading "+index+": malformed";
  if(typeof entry.channel!=="string"||entry.channel.length===0)return"reading "+index+": bad channel";
  if(UNITS.indexOf(entry.unit)<0)return"reading "+index+": bad unit";
  if(!Number.isInteger(entry.value))return"reading "+index+": bad value";
  if(!Number.isInteger(entry.at)||entry.at<0)return"reading "+index+": bad timestamp";
  return{channel:entry.channel,unit:entry.unit,value:entry.value,at:entry.at};
}
function origNorm(unit,value){
  if(unit==="V")return value*1000;
  if(unit==="uV")return Math.trunc(value/1000);
  return value;
}
function origAlerts(parsed){
  const a=[];
  for(const r of parsed){
    if(r.millivolts>=900)a.push(r.channel+":critical");
    else if(r.millivolts<0)a.push(r.channel+":negative");
    else if(r.millivolts>=600&&r.millivolts<900)a.push(r.channel+":loaded");
  }
  return a;
}
function origSummaries(parsed,labels){
  const c={};
  for(let i=0;i<parsed.length;i++){
    const r=parsed[i];
    const e=c[r.channel];
    if(e===undefined){c[r.channel]={count:1,min:r.millivolts,max:r.millivolts,worst:labels[i]};continue;}
    e.count=e.count+1;
    if(r.millivolts<e.min)e.min=r.millivolts;
    if(r.millivolts>e.max)e.max=r.millivolts;
    if(origSeverity(labels[i])>origSeverity(e.worst))e.worst=labels[i];
  }
  return c;
}
function origReport(rc,cc,ac,labels){
  let w="standby";
  for(const l of labels){if(origSeverity(l)>origSeverity(w))w=l;}
  return "readings="+rc+";channels="+cc+";alerts="+ac+";worst="+w;
}

function deepEq(a,b){
  return JSON.stringify(a)===JSON.stringify(b);
}

let fails=0, tests=0;
function check(name,input){
  tests++;
  const a=processBatch(input);
  const b=origProcess(input);
  if(!deepEq(a,b)){fails++; console.log("FAIL",name,"\n got:",JSON.stringify(a),"\n exp:",JSON.stringify(b));}
}

// classify edge cases
for(const mv of [-1,-0.0001,0,1,49,50,199,200,599,600,899,900,1000,1500,54.5]){
  tests++; const a=classifySignal(mv),b=origClassify(mv);
  if(a!==b){fails++;console.log("FAIL classify",mv,a,b);}
}

// malformed / validation
check("null",null);
check("num",42);
check("str","hi");
check("obj no readings",{});
check("readings not array",{readings:{}});
check("empty",{readings:[]});
const big={readings:Array.from({length:501},()=>({channel:"c",unit:"mV",value:1,at:0}))};
check("too large",big);

// random valid + malformed batches
const channels=["a","","b!",12,"long",null];
const units=["mV","uV","V","W",42,null];
for(let t=0;t<20000;t++){
  const n=1+Math.floor(Math.random()*20);
  const arr=[];
  for(let i=0;i<n;i++){
    const r=Math.random();
    if(r<0.3){ arr.push(Math.random()<0.5?null:(Math.random()<0.5?42:"x")); continue; }
    const ch=channels[Math.floor(Math.random()*channels.length)];
    const un=units[Math.floor(Math.random()*units.length)];
    const cn=Math.random()<0.85?"c"+Math.floor(Math.random()*5):"a";
    const val = Math.random()<0.2 ? (Math.random()<0.5?"s":1.5) : (Math.floor(Math.random()*2600)-400);
    const at = Math.random()<0.15 ? -5 : Math.floor(Math.random()*1000);
    arr.push({channel:ch,unit:un,value:val,at});
    void cn;
  }
  check("rand"+t,{readings:arr});
}
console.log(`done tests=${tests} fails=${fails}`);
