content.text:
export interface Reading {
  channel: string;
  unit: string;
  value: number;
  at: number;
}

interface ParsedReading {
  channel: string;
  millivolts: number;
  at: number;
}

interface ChannelSummary {
  count: number;
  min: number;
  max: number;
  worst: string;
}

export interface BatchResult {
  ok: boolean;
  error?: string;
  readings?: number;
  labels?: string[];
  channels?: Record<string, ChannelSummary>;
  alerts?: string[];
  report?: string;
}

const MAX_READINGS = 500;

// Each unit maps straight to a millivolt conversion; a lookup replaces three branches.
const UNIT_NORMALIZE: Record<string, (value: number) => number> = {
  V: (value) => value * 1000,
  uV: (value) => Math.trunc(value / 1000),
  mV: (value) => value,
};

// Signal bands keyed by upper bound; classifySignal scans high-to-low so the highest matching band wins.
const SIGNAL_SEGMENTS: ReadonlyArray<readonly [number, string]> = [
  [0, "standby"],
  [50, "idle"],
  [200, "active"],
  [600, "loaded"],
  [900, "critical"],
];

const SEVERITY_RANK: Record<string, number> = {
  standby: 0,
  idle: 1,
  active: 2,
  loaded: 3,
  critical: 4,
  negative: 5,
};

// Alerts are just the subset of signal labels worth reporting.
const ALERT_LABELS = new Set(["negative", "loaded", "critical"]);

export function processBatch(raw: unknown): BatchResult {
  const batchError = validateBatch(raw);
  if (batchError !== null) {
    return { ok: false, error: batchError };
  }
  const entries = (raw as { readings: unknown[] }).readings;
  const parsed: ParsedReading[] = [];
  for (let index = 0; index < entries.length; index++) {
    const outcome = parseReading(entries[index], index);
    if (typeof outcome === "string") {
