  const a=[];
  for(const r of parsed){
    if(r.millivolts>=900)a.push(r.channel+":critical");
    else if(r.millivolts<0)a.push(r.channel+":negative");
    else if(r.millivolts>=600&&r.millivolts<900)a.push(r.channel+":loaded");
